class Solution {

    /**
     * @param Integer $left
     * @param Integer $right
     * @return String
     */
    function abbreviateProduct($left, $right) {
        $v2 = 0;
        $v5 = 0;
        $logSum = 0.0;

        // First pass: compute total powers of 2 and 5, and sum of log10(i)
        for ($i = $left; $i <= $right; $i++) {
            $logSum += log10($i);
            $x = $i;
            while ($x % 2 == 0) {
                $v2++;
                $x = intdiv($x, 2);
            }
            while ($x % 5 == 0) {
                $v5++;
                $x = intdiv($x, 5);
            }
        }

        $C = min($v2, $v5);
        $logR = $logSum - $C;
        $d_approx = floor($logR) + 1;

        // If the remaining number is small enough, compute it exactly.
        if ($d_approx <= 18) {
            $res = 1;
            for ($i = $left; $i <= $right; $i++) {
                $x = $i;
                while ($x % 2 == 0) $x = intdiv($x, 2);
                while ($x % 5 == 0) $x = intdiv($x, 5);
                $res *= $x;
            }
            $diff2 = $v2 - $C;
            $diff5 = $v5 - $C;
            while ($diff2-- > 0) $res *= 2;
            while ($diff5-- > 0) $res *= 5;

            $s = (string)$res;
            $d = strlen($s);
            if ($d <= 10) {
                return $s . "e" . $C;
            } else {
                return substr($s, 0, 5) . "..." . substr($s, -5) . "e" . $C;
            }
        }

        // Otherwise, compute only the last five digits and the first five digits.
        $res = 1;
        for ($i = $left; $i <= $right; $i++) {
            $x = $i;
            while ($x % 2 == 0) $x = intdiv($x, 2);
            while ($x % 5 == 0) $x = intdiv($x, 5);
            $res = ($res * ($x % 100000)) % 100000;
        }
        $diff2 = $v2 - $C;
        $diff5 = $v5 - $C;
        while ($diff2-- > 0) $res = ($res * 2) % 100000;
        while ($diff5-- > 0) $res = ($res * 5) % 100000;

        $suffix = str_pad((string)$res, 5, '0', STR_PAD_LEFT);

        $frac = $logSum - floor($logSum);
        $prefix = (int)floor(pow(10, $frac + 4));
        if ($prefix > 99999) $prefix = 99999;
        if ($prefix < 10000) $prefix = 10000;

        return $prefix . "..." . $suffix . "e" . $C;
    }
}
```

