class Solution {

    /**
     * @param Integer[] $tasks
     * @param Integer $sessionTime
     * @return Integer
     */
    function minSessions($tasks, $sessionTime) {
        $n = count($tasks);
        $total = 1 << $n;

        $sessions = array_fill(0, $total, PHP_INT_MAX);
        $used = array_fill(0, $total, 0);

        $sessions[0] = 0;
        $used[0] = 0;

        for ($mask = 0; $mask < $total; $mask++) {
            if ($sessions[$mask] === PHP_INT_MAX) {
                continue;
            }

            for ($i = 0; $i < $n; $i++) {
                if ($mask & (1 << $i)) {
                    continue;
                }

                $next = $mask | (1 << $i);
                $t = $tasks[$i];

                if ($used[$mask] + $t <= $sessionTime) {
                    $nextSessions = $sessions[$mask];
                    $nextUsed = $used[$mask] + $t;
                } else {
                    $nextSessions = $sessions[$mask] + 1;
                    $nextUsed = $t;
                }

                if (
                    $nextSessions < $sessions[$next] ||
                    ($nextSessions === $sessions[$next] && $nextUsed < $used[$next])
                ) {
                    $sessions[$next] = $nextSessions;
                    $used[$next] = $nextUsed;
                }
            }
        }

        return $sessions[$total - 1];
    }
}
