class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function ambiguousCoordinates($s) {
        $digits = substr($s, 1, strlen($s) - 2);
        $n = strlen($digits);
        $result = [];

        for ($i = 1; $i < $n; $i++) {
            $left = substr($digits, 0, $i);
            $right = substr($digits, $i);

            $leftVals = $this->validNumbers($left);
            $rightVals = $this->validNumbers($right);

            foreach ($leftVals as $l) {
                foreach ($rightVals as $r) {
                    $result[] = "($l, $r)";
                }
            }
        }

        return $result;
    }

    private function validNumbers($str) {
