class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function ambiguousCoordinates($s) {
        $digits = substr($s, 1, strlen($s) - 2);
        $n = strlen($digits);
        $result = [];
        for ($i = 1; $i < $n; $i++) {
            $left = substr($digits, 0, $i);
            $right = substr($digits, $i);
            $leftVals = $this->validNumbers($left);
            $rightVals = $this->validNumbers($right);
            foreach ($leftVals as $l) {
                foreach ($rightVals as $r) {
                    $result[] = "($l, $r)";
                }
            }
        }
        return $result;
    }

    private function validNumbers($str) {
        $vals = [];
        $len = strlen($str);

        if ($len == 1 || $str[0] != '0') {
            $vals[] = $str;
        }

        for ($i = 1; $i < $len; $i++) {
            $intPart = substr($str, 0, $i);
            $fracPart = substr($str, $i);

            if ($intPart[0] == '0' && strlen($intPart) > 1) {
                continue;
            }
            if ($fracPart[strlen($fracPart) - 1] == '0') {
                continue;
            }
            $vals[] = $intPart . '.' . $fracPart;
        }

        return $vals;
    }
}
