class MKAverage {
    private $m;
    private $k;
    private $bitCount;
    private $bitSum;
    private $queue;
    private $head;
    private $total;
    private $maxVal;

    function __construct($m, $k) {
        $this->m = $m;
        $this->k = $k;
        $this->maxVal = 100000;
        $this->bitCount = array_fill(0, $this->maxVal + 2, 0);
        $this->bitSum = array_fill(0, $this->maxVal + 2, 0);
        $this->queue = [];
        $this->head = 0;
        $this->total = 0;
    }

    private function update($val, $dc, $ds) {
        for ($i = $val; $i <= $this->maxVal; $i += ($i & -$i)) {
            $this->bitCount[$i] += $dc;
            $this->bitSum[$i] += $ds;
        }
    }

    private function sumSmallest($k) {
        if ($k <= 0) return 0;
        $idx = 0;
        $cnt = 0;
        $sum = 0;
        $bit = 1;
        while (($bit << 1) <= $this->maxVal) {
            $bit <<= 1;
        }
        for (; $bit > 0; $bit >>= 1) {
            $next = $idx + $bit;
            if ($next <= $this->maxVal && $cnt + $this->bitCount[$next] < $k) {
                $idx = $next;
                $cnt += $this->bitCount[$next];
                $sum += $this->bitSum[$next];
            }
        }
        $rem = $k - $cnt;
        $value = $idx + 1;
        return $sum + $rem * $value;
    }

    function addElement($num) {
        $this->total++;
        if ($this->total > $this->m) {
            $old = $this->queue[$this->head++];
            $this->update($old, -1, -$old);
        }
        $this->queue[] = $num;
        $this->update($num, 1, $num);
    }

    function calculateMKAverage() {
        if ($this->total < $this->m) return -1;
        $smallK = $this->sumSmallest($this->k);
        $smallMK = $this->sumSmallest($this->m - $this->k);
        $middleSum = $smallMK - $smallK;
        return intdiv($middleSum, $this->m - 2 * $this->k);
    }
}
