class Solution {
    function canCross($stones) {
        $n = count($stones);
        if ($n <= 1) return true;
        $index = [];
        foreach ($stones as $i => $pos) {
            $index[$pos] = $i;
        }
        $maxK = $n + 1;
        $bytes = intdiv($maxK, 8) + 1;
        $dp = array_fill(0, $n, str_repeat("\0", $bytes));
        $dp[0][0] = chr(1);
        for ($i = 0; $i < $n; $i++) {
            $bits = $dp[$i];
            for ($k = 0; $k <= $maxK; $k++) {
                if ((ord($bits[$k >> 3]) >> ($k & 7)) & 1) {
                    for ($delta = -1; $delta <= 1; $delta++) {
                        $nk = $k + $delta;
                        if ($nk <= 0 || $nk > $maxK) continue;
                        $nextPos = $stones[$i] + $nk;
                        if (isset($index[$nextPos])) {
                            $j = $index[$nextPos];
                            $byte = $nk >> 3;
                            $mask = 1 << ($nk & 7);
                            $dp[$j][$byte] = chr(ord($dp[$j][$byte]) | $mask);
                        }
                    }
                }
            }
        }
        for ($b = 0; $b < $bytes; $b++) {
            if (ord($dp[$n - 1][$b]) != 0) return true;
        }
        return false;
    }
}
```

