class Solution {

    /**
     * @param ListNode $head
     * @param Integer[] $nums
     * @return Integer
     */
    function numComponents($head, $nums) {
        $set = array_flip($nums);
        $count = 0;
        $cur = $head;

        while ($cur !== null) {
            if (isset($set[$cur->val])) {
                if ($cur->next === null || !isset($set[$cur->next->val])) {
                    $count++;
                }
            }
            $cur = $cur->next;
        }

        return $count;
    }
}
