```php
class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function maxScore($nums) {
        $m = count($nums);
        $totalMasks = 1 << $m;
        $dp = array_fill(0, $totalMasks, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $totalMasks; $mask++) {
            if ($dp[$mask] < 0) {
                continue;
            }

            $used = 0;
            $tmp = $mask;
            while ($tmp > 0) {
                $used += $tmp & 1;
                $tmp >>= 1;
            }

            if ($used % 2 != 0) {
                continue;
            }

            $operation = ($used >> 1) + 1;

            for ($i = 0; $i < $m; $i++) {
                if (($mask >> $i) & 1) {
                    continue;
                }

                for ($j = $i + 1; $j < $m; $j++) {
                    if (($mask >> $j) & 1) {
                        continue;
                    }

                    $newMask = $mask | (1 << $i) | (1 << $j);
                    $score = $dp[$mask] + $operation * $this->gcd($nums[$i], $nums[$j]);

                    if ($score > $dp[$newMask]) {
                        $dp[$newMask] = $score;
                    }
                }
            }
        }

        return $dp[$totalMasks - 1];
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $t = $a % $b;
            $a = $b;
            $b = $t;
        }
        return $a;
    }
}
```

