    function maximumANDSum($nums, $numSlots) {
        $n = count($nums);
        $m = 2 * $numSlots;
        $total = 1 << $m;

        $dp = array_fill(0, $total, -1);
        $dp[0] = 0;

        $cnt = array_fill(0, $total, 0);
        for ($i = 1; $i < $total; $i++) {
            $cnt[$i] = $cnt[$i >> 1] + ($i & 1);
        }

        $slot = [];
        for ($i = 0; $i < $m; $i++) {
            $slot[$i] = intdiv($i, 2) + 1;
        }

        $ans = 0;

        for ($mask = 0; $mask < $total; $mask++) {
            $cur = $dp[$mask];
            if ($cur < 0) {
                continue;
