class Solution {

    /**
     * @param Integer[][] $students
     * @param Integer[][] $mentors
     * @return Integer
     */
    function maxCompatibilitySum($students, $mentors) {
        $m = count($students);
        $n = count($students[0]);

        $score = array_fill(0, $m, array_fill(0, $m, 0));

        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $m; $j++) {
                $compat = 0;
                for ($k = 0; $k < $n; $k++) {
                    if ($students[$i][$k] == $mentors[$j][$k]) {
                        $compat++;
                    }
                }
                $score[$i][$j] = $compat;
            }
        }

        $totalMasks = 1 << $m;
        $dp = array_fill(0, $totalMasks, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask < $totalMasks; $mask++) {
            if ($dp[$mask] == -1) {
                continue;
            }

            $assignedStudents = 0;
            $tmp = $mask;
            while ($tmp > 0) {
                $assignedStudents += $tmp & 1;
                $tmp >>= 1;
            }

            if ($assignedStudents >= $m) {
                continue;
