Let's write robust PHP syntax.

class Solution {

    /**
     * @param Integer[] $nums
     * @return Integer
     */
    function maxEqualFreq($nums) {
        $freq = [];
        $cnt = [];
        $maxFreq = 0;
        $ans = 0;
        $n = count($nums);
        for ($i = 0; $i < $n; $i++) {
            $x = $nums[$i];
            $old = isset($freq[$x]) ? $freq[$x] : 0;
            if ($old > 0) {
                $cnt[$old]--;
            }
            $new = $old + 1;
            $freq[$x] = $new;
            if (!isset($cnt[$new])) {
                $cnt[$new] = 0;
            }
            $cnt[$new]++;
            if ($new > $maxFreq) {
                $maxFreq = $new;
            }

            $len = $i + 1;
            $valid = false;
            if ($maxFreq == 1) {
                $valid = true;
            } else {
                $cM = isset($cnt[$maxFreq]) ? $cnt[$maxFreq] : 0;
                if ($cM == 1) {
                    $prev = $maxFreq - 1;
                    $cPrev = isset($cnt[$prev]) ? $cnt[$prev] : 0;
                    if ($cPrev * $prev == $len - $maxFreq) {
                        $valid = true;
                    }
                }
                if (!$valid) {
                    $cM = isset($cnt[$maxFreq]) ? $cnt[$maxFreq] : 0;
                    if ($cM * $maxFreq == $len - 1) {
                        $valid = true;
                    }
                }
            }
            if ($valid) {
                $ans = $len;
            }
        }
        return $ans;
    }
}

