```php
class Solution {

    /**
     * @param Integer[][] $fruits
     * @param Integer $startPos
     * @param Integer $k
     * @return Integer
     */
    function maxTotalFruits($fruits, $startPos, $k) {
        $n = count($fruits);
        $left = 0;
        $sum = 0;
        $maxFruits = 0;

        for ($right = 0; $right < $n; $right++) {
            $sum += $fruits[$right][1];

            while ($left <= $right) {
                $lPos = $fruits[$left][0];
                $rPos = $fruits[$right][0];

                $width = $rPos - $lPos;
                $distToLeft = abs($startPos - $lPos);
                $distToRight = abs($startPos - $rPos);
                $cost = $width + min($distToLeft, $distToRight);

                if ($cost <= $k) {
                    break;
                }

                $sum -= $fruits[$left][1];
                $left++;
            }

            if ($sum > $maxFruits) {
                $maxFruits = $sum;
            }
        }

        return $maxFruits;
    }
}
```

