class Solution {

    /**
     * @param String[][] $seats
     * @return Integer
     */
    function maxStudents($seats) {
        $m = count($seats);
        if ($m == 0) return 0;

        $firstRow = $seats[0];
        $n = is_array($firstRow) ? count($firstRow) : strlen($firstRow);

        $rowMasks = [];
        for ($i = 0; $i < $m; $i++) {
            $row = $seats[$i];
            $mask = 0;
            for ($j = 0; $j < $n; $j++) {
                $ch = is_array($row) ? $row[$j] : $row[$j];
                if ($ch === '.') {
                    $mask |= 1 << $j;
                }
            }
            $rowMasks[$i] = $mask;
        }

        $totalMasks = 1 << $n;

        $popcount = array_fill(0, $totalMasks, 0);
        for ($mask = 1; $mask < $totalMasks; $mask++) {
            $popcount[$mask] = $popcount[$mask >> 1] + ($mask & 1);
        }

        $NEG_INF = -1000000;
        $dp = array_fill(0, $totalMasks, $NEG_INF);
        $dp[0] = 0;

        for ($i = 0; $i < $m; $i++) {
            $newDp = array_fill(0, $totalMasks, $NEG_INF);
            $allowed = $rowMasks[$i];

            for ($cur = 0; $cur < $totalMasks; $cur++) {
                if (($cur & $allowed) !== $cur) continue;
                if (($cur & ($cur << 1)) !== 0) continue;

                for ($prev = 0; $prev < $totalMasks; $prev++) {
                    if ($dp[$prev] === $NEG_INF) continue;

                    if ((($prev & ($cur << 1)) !== 0) || (($prev & ($cur >> 1)) !== 0)) {
                        continue;
                    }

                    $value = $dp[$prev] + $popcount[$cur];
                    if ($value > $newDp[$cur]) {
                        $newDp[$cur] = $value;
                    }
                }
            }

            $dp = $newDp;
        }

        return max($dp);
    }
}
```

