    function minMalwareSpread($graph, $initial) {
        $n = count($graph);
        sort($initial);

        $bestNode = -1;
        $bestCount = PHP_INT_MAX;

        foreach ($initial as $remove) {
            $visited = array_fill(0, $n, false);
            $queue = [];

            foreach ($initial as $start) {
                if ($start == $remove) {
                    continue;
                }
                if (!$visited[$start]) {
                    $visited[$start] = true;
                    $queue[] = $start;
                }
