class Solution {

    /**
     * @param Integer $maxTime
     * @param Integer[][] $edges
     * @param Integer[] $passingFees
     * @return Integer
     */
    function minCost($maxTime, $edges, $passingFees) {
        $n = count($passingFees);
        $INF = 1000000000;

        // dp[t][i] = minimum cost to reach city i at exactly time t
        $dp = [];
        for ($t = 0; $t <= $maxTime; $t++) {
            $dp[$t] = array_fill(0, $n, $INF);
        }

        // Start at city 0, paying its passing fee
        $dp[0][0] = $passingFees[0];

        for ($t = 0; $t < $maxTime; $t++) {
            $row = &$dp[$t];

            foreach ($edges as $e) {
                $u = $e[0];
                $v = $e[1];
                $w = $e[2];
                $nt = $t + $w;

                if ($nt > $maxTime) {
                    continue;
                }

                // Move u -> v
                if ($row[$u] != $INF) {
                    $nc = $row[$u] + $passingFees[$v];
                    if ($nc < $dp[$nt][$v]) {
                        $dp[$nt][$v] = $nc;
                    }
                }

                // Move v -> u
                if ($row[$v] != $INF) {
                    $nc = $row[$v] + $passingFees[$u];
                    if ($nc < $dp[$nt][$u]) {
                        $dp[$nt][$u] = $nc;
                    }
                }
            }

            unset($row);
        }

        $ans = $INF;
        for ($t = 0; $t <= $maxTime; $t++) {
            if ($dp[$t][$n - 1] < $ans) {
                $ans = $dp[$t][$n - 1];
            }
        }

        return $ans == $INF ? -1 : $ans;
    }
}
