class Solution {
    function minDays($bloomDay, $m, $k) {
        $n = count($bloomDay);
        if ($m * $k > $n) return -1;
        $low = 1;
        $high = max($bloomDay);
        while ($low < $high) {
            $mid = intdiv($low + $high, 2);
            if ($this->canMake($bloomDay, $m, $k, $mid)) {
                $high = $mid;
            } else {
                $low = $mid + 1;
            }
        }
        return $low;
    }
    private function canMake($bloomDay, $m, $k, $day) {
        $bouquets = 0;
        $count = 0;
        foreach ($bloomDay as $b) {
            if ($b <= $day) {
                $count++;
                if ($count == $k) {
                    $bouquets++;
                    $count = 0;
                    if ($bouquets >= $m) return true;
                }
            } else {
                $count = 0;
            }
        }
        return $bouquets >= $m;
    }
}

