class Solution {
    /**
     * @param Integer[] $target
     * @return Integer
     */
    function minNumberOperations($target) {
        $ans = 0;
        $prev = 0;
        foreach ($target as $v) {
            if ($v > $prev) {
                $ans += $v - $prev;
            }
            $prev = $v;
        }
        return $ans;
    }
}
