```php
class Solution {

    /**
     * @param Integer[] $slices
     * @return Integer
     */
    function maxSizeSlices($slices) {
        $m = count($slices);
        $n = intdiv($m, 3);

        $solve = function($arr, $n) {
            $len = count($arr);
            $NEG = -1000000000;

            $dp = array_fill(0, $len + 1, array_fill(0, $n + 1, $NEG));
            $dp[0][0] = 0;

            for ($i = 1; $i <= $len; $i++) {
                $dp[$i][0] = 0;
                $maxJ = min($n, intdiv($i + 1, 2));

                for ($j = 1; $j <= $maxJ; $j++) {
                    $notTake = $dp[$i - 1][$j];
                    $take = $NEG;

                    if ($j == 1) {
                        $take = $arr[$i - 1];
                    } elseif ($i >= 2 && $dp[$i - 2][$j - 1] != $NEG) {
                        $take = $dp[$i - 2][$j - 1] + $arr[$i - 1];
                    }

                    $dp[$i][$j] = max($notTake, $take);
                }
            }

            return $dp[$len][$n];
        };

        $case1 = $solve(array_slice($slices, 0, $m - 1), $n);
        $case2 = $solve(array_slice($slices, 1, $m - 1), $n);

        return max($case1, $case2);
    }
}
