class Solution {

    /**
     * @param Integer $n
     * @param Integer[][] $restrictions
     * @param Integer[][] $requests
     * @return Boolean[]
     */
    function friendRequests($n, $restrictions, $requests) {
        $parent = range(0, $n - 1);

        $find = function($x) use (&$parent) {
            $root = $x;
            while ($parent[$root] !== $root) {
                $root = $parent[$root];
            }

            while ($parent[$x] !== $x) {
                $next = $parent[$x];
                $parent[$x] = $root;
                $x = $next;
            }

            return $root;
        };

        $result = [];

        foreach ($requests as $request) {
            $u = $request[0];
            $v = $request[1];

            $ru = $find($u);
            $rv = $find($v);

            if ($ru === $rv) {
                $result[] = true;
                continue;
            }

            $canBefriend = true;

            foreach ($restrictions as $restriction) {
                $x = $restriction[0];
                $y = $restriction[1];

                $rx = $find($x);
                $ry = $find($y);

                if (($rx === $ru && $ry === $rv) || ($rx === $rv && $ry === $ru)) {
                    $canBefriend = false;
                    break;
                }
            }

            if ($canBefriend) {
                $parent[$ru] = $rv;
                $result[] = true;
            } else {
                $result[] = false;
            }
        }

        return $result;
    }
}
