class Solution {
    private $positions = [];

    /**
     * @param Integer[] $nums
     */
    function __construct($nums) {
        foreach ($nums as $index => $num) {
            if (!isset($this->positions[$num])) {
                $this->positions[$num] = [];
            }
            $this->positions[$num][] = $index;
        }
    }

    /**
     * @param Integer $target
     * @return Integer
     */
    function pick($target) {
        $indices = $this->positions[$target];
        return $indices[array_rand($indices)];
    }
}
