class Solution {

    /**
     * @param String[] $grid
     * @return Integer
     */
    function regionsBySlashes($grid) {
        $n = count($grid);
        $m = 3 * $n;

        $a = [];
        for ($i = 0; $i < $m; $i++) {
            $a[$i] = array_fill(0, $m, 0);
        }

        for ($i = 0; $i < $n; $i++) {
            for ($j = 0; $j < $n; $j++) {
                $ch = $grid[$i][$j];
                $r = 3 * $i;
                $c = 3 * $j;

                if ($ch == '/') {
                    $a[$r][$c + 2] = 1;
                    $a[$r + 1][$c + 1] = 1;
                    $a[$r + 2][$c] = 1;
                } elseif ($ch == '\\') {
                    $a[$r][$c] = 1;
                    $a[$r + 1][$c + 1] = 1;
                    $a[$r + 2][$c + 2] = 1;
                }
            }
        }

        $regions = 0;
        $dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

        for ($i = 0; $i < $m; $i++) {
            for ($j = 0; $j < $m; $j++) {
                if ($a[$i][$j] == 0) {
                    $regions++;
                    $a[$i][$j] = 2;
                    $queue = [[$i, $j]];
                    $head = 0;

                    while ($head < count($queue)) {
                        $x = $queue[$head][0];
                        $y = $queue[$head][1];
                        $head++;

                        foreach ($dirs as $d) {
                            $nx = $x + $d[0];
                            $ny = $y + $d[1];

                            if ($nx >= 0 && $nx < $m && $ny >= 0 && $ny < $m && $a[$nx][$ny] == 0) {
                                $a[$nx][$ny] = 2;
                                $queue[] = [$nx, $ny];
                            }
                        }
                    }
                }
            }
        }

        return $regions;
    }
}
```

