class Solution {

    /**
     * @param String $s
     * @return String[]
     */
    function removeInvalidParentheses($s) {
        $left = 0;
        $right = 0;
        $n = strlen($s);
        for ($i = 0; $i < $n; $i++) {
            $c = $s[$i];
            if ($c == '(') {
                $left++;
            } elseif ($c == ')') {
                if ($left > 0) {
                    $left--;
                } else {
                    $right++;
                }
            }
        }
        $result = [];
        $this->dfs($s, 0, 0, $left, $right, '', $result, $n);
        return array_keys($result);
    }

    private function dfs($s, $i, $balance, $left, $right, $curr, &$result, $n) {
        if ($left + $right > $n - $i) {
            return;
        }
        if ($i == $n) {
            if ($left == 0 && $right == 0 && $balance == 0) {
                $result[$curr] = true;
            }
            return;
        }
        $c = $s[$i];
        if ($c == '(') {
            if ($left > 0) {
                $this->dfs($s, $i + 1, $balance, $left - 1, $right, $curr, $result, $n);
            }
            $this->dfs($s, $i + 1, $balance + 1, $left, $right, $curr . '(', $result, $n);
        } elseif ($c == ')') {
            if ($right > 0) {
                $this->dfs($s, $i + 1, $balance, $left, $right - 1, $curr, $result, $n);
            }
            if ($balance > 0) {
                $this->dfs($s, $i + 1, $balance - 1, $left, $right, $curr . ')', $result, $n);
            }
        } else {
            $this->dfs($s, $i + 1, $balance, $left, $right, $curr . $c, $result, $n);
        }
    }
}
