class Solution {
    function removeInvalidParentheses($s) {
        $left = 0; $right = 0;
        $n = strlen($s);
        for ($i=0; $i<$n; $i++) {
            $c = $s[$i];
            if ($c == '(') {
                $left++;
            } elseif ($c == ')') {
                if ($left > 0) {
                    $left--;
                } else {
                    $right++;
                }
            }
        }
        $result = [];
        $this->dfs($s, 0, 0, $left, $right, '', $result);
        return array_keys($result);
    }

    private function dfs($s, $i, $balance, $left, $right, $curr, &$result) {
        $n = strlen($s);
        if ($i == $n) {
            if ($left == 0 && $right == 0 && $balance == 0) {
                $result[$curr] = true;
            }
            return;
        }
        $c = $s[$i];
        if ($c == '(') {
            // remove
            if ($left > 0) {
                $this->dfs($s, $i+1, $balance, $left-1, $right, $curr, $result);
            }
            // keep
            $this->dfs($s, $i+1, $balance+1, $left, $right, $curr.'(', $result);
        } elseif ($c == ')') {
            // remove
            if ($right > 0) {
                $this->dfs($s, $i+1, $balance, $left, $right-1, $curr, $result);
            }
            // keep
            if ($balance > 0) {
                $this->dfs($s, $i+1, $balance-1, $left, $right, $curr.')', $result);
            }
        } else {
            $this->dfs($s, $i+1, $balance, $left, $right, $curr.$c, $result);
        }
    }
}

