class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer $k
     * @return Integer
     */
    function splitArray($nums, $k) {
        $left = 0;
        $right = 0;

        foreach ($nums as $num) {
            if ($num > $left) {
                $left = $num;
            }
            $right += $num;
        }

        while ($left < $right) {
            $mid = $left + intdiv($right - $left, 2);

            if ($this->canSplit($nums, $k, $mid)) {
                $right = $mid;
            } else {
                $left = $mid + 1;
            }
        }

        return $left;
    }

    private function canSplit($nums, $k, $maxSum) {
        $parts = 1;
        $currentSum = 0;

        foreach ($nums as $num) {
            if ($currentSum + $num > $maxSum) {
                $parts++;
                $currentSum = $num;

                if ($parts > $k) {
                    return false;
                }
            } else {
                $currentSum += $num;
            }
        }

        return true;
    }
}
