```php
class Solution {

    /**
     * @param String[] $stickers
     * @param String $target
     * @return Integer
     */
    function minStickers($stickers, $target) {
        $m = strlen($target);
        $full = (1 << $m) - 1;

        $targetCnt = array_fill(0, 26, 0);
        $targetIdx = array_fill(0, $m, 0);
        $charMask = array_fill(0, 26, 0);

        for ($i = 0; $i < $m; $i++) {
            $idx = ord($target[$i]) - 97;
            $targetIdx[$i] = $idx;
            $targetCnt[$idx]++;
            $charMask[$idx] |= (1 << $i);
        }

        $stickersByChar = array_fill(0, 26, []);
        $seen = [];

        foreach ($stickers as $s) {
            $cnt = array_fill(0, 26, 0);
            $len = strlen($s);
            for ($i = 0; $i < $len; $i++) {
                $c = ord($s[$i]) - 97;
                $cnt[$c]++;
            }

            $sum = 0;
            for ($c = 0; $c < 26; $c++) {
                if ($targetCnt[$c] == 0) {
                    $cnt[$c] = 0;
                } elseif ($cnt[$c] > $targetCnt[$c]) {
                    $cnt[$c] = $targetCnt[$c];
                }
                $sum += $cnt[$c];
            }
            if ($sum == 0) continue;

            $key = implode(',', $cnt);
            if (isset($seen[$key])) continue;
            $seen[$key] = true;

            $compact = [];
            for ($c = 0; $c < 26; $c++) {
                if ($cnt[$c] > 0) {
                    $compact[$c] = $cnt[$c];
                }
            }

            foreach ($compact as $c => $n) {
                $stickersByChar[$c][] = $compact;
            }
        }

        $dist = array_fill(0, 1 << $m, -1);
        $dist[0] = 0;
        $queue = [0];
        $head = 0;

        while ($head < count($queue)) {
            $mask = $queue[$head++];

            if ($mask == $full) {
                return $dist[$mask];
            }

            $i = 0;
            while (($mask & (1 << $i)) != 0) {
                $i++;
            }
            $needIdx = $targetIdx[$i];

            foreach ($stickersByChar[$needIdx] as $compact) {
                $newMask = $mask;
                foreach ($compact as $c => $n) {
                    $missing = $charMask[$c] & ~$mask;
                    while ($n > 0 && $missing != 0) {
                        $bit = $missing & -$missing;
                        $newMask |= $bit;
                        $missing ^= $bit;
                        $n--;
                    }
                }

                if ($newMask != $mask && $dist[$newMask] == -1) {
                    $dist[$newMask] = $dist[$mask] + 1;
                    $queue[] = $newMask;
                }
            }
        }

        return -1;
    }
}
```

