            $idx = ord($target[$i]) - 97;
            $targetIdx[$i] = $idx;
            $targetCnt[$idx]++;
            $charMask[$idx] |= (1 << $i);
        }

        $stickersByChar = array_fill(0, 26, []);
        $seen = [];
        foreach ($stickers as $s) {
            $cnt = array_fill(0, 26, 0);
            $len = strlen($s);
            for ($i = 0; $i < $len; $i++) {
                $c = ord($s[$i]) - 97;
                $cnt[$c]++;
            }
            $sum = 0;
            for ($c = 0; $c < 26; $c++) {
                if ($targetCnt[$c] == 0) {
                    $cnt[$c] = 0;
                } elseif ($cnt[$c] > $targetCnt[$c]) {
                    $cnt[$c] = $targetCnt[$c];
