class Solution {

    /**
     * @param Integer $n
     * @param Integer $firstPlayer
     * @param Integer $secondPlayer
     * @return Integer[]
     */
    function earliestAndLatest($n, $firstPlayer, $secondPlayer) {
        $memo = [];

        $dfs = function($n, $a, $b) use (&$dfs, &$memo) {
            if ($a > $b) {
                $tmp = $a;
                $a = $b;
                $b = $tmp;
            }

            if ($a + $b == $n + 1) {
                return [1, 1];
            }

            $key = $n . ':' . $a . ':' . $b;
            if (isset($memo[$key])) {
                return $memo[$key];
            }

            $pairs = intdiv($n, 2);
            $middle = ($n % 2) ? intdiv($n + 1, 2) : 0;

            $freeCount = 0;
            for ($i = 1; $i <= $pairs; $i++) {
                $low = $i;
                $high = $n + 1 - $i;
                if (($low != $a && $high != $a) && ($low != $b && $high != $b)) {
                    $freeCount++;
                }
            }

            $bestEarly = PHP_INT_MAX;
            $bestLate = -1;
            $limit = 1 << $freeCount;

            for ($mask = 0; $mask < $limit; $mask++) {
                $winners = [];
                $bit = 0;

                for ($i = 1; $i <= $pairs; $i++) {
                    $low = $i;
                    $high = $n + 1 - $i;

                    if ($low == $a || $high == $a) {
                        $winners[] = $a;
                    } elseif ($low == $b || $high == $b) {
                        $winners[] = $b;
                    } else {
                        if (($mask >> $bit) & 1) {
                            $winners[] = $high;
                        } else {
                            $winners[] = $low;
                        }
                        $bit++;
                    }
                }

                if ($middle) {
                    if ($middle == $a) {
                        $winners[] = $a;
                    } elseif ($middle == $b) {
                        $winners[] = $b;
                    } else {
                        $winners[] = $middle;
                    }
                }

                sort($winners);
                $newA = array_search($a, $winners) + 1;
                $newB = array_search($b, $winners) + 1;

                $res = $dfs(count($winners), $newA, $newB);
                $early = $res[0] + 1;
                $late = $res[1] + 1;

                if ($early < $bestEarly) {
                    $bestEarly = $early;
                }
                if ($late > $bestLate) {
                    $bestLate = $late;
                }
            }

            $memo[$key] = [$bestEarly, $bestLate];
            return $memo[$key];
        };

        return $dfs($n, $firstPlayer, $secondPlayer);
