class Solution {

    /**
     * @param Integer[] $nums
     * @param Integer[][] $edges
     * @return Integer[]
     */
    function getCoprimes($nums, $edges) {
        $n = count($nums);
        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $u = $e[0];
            $v = $e[1];
            $adj[$u][] = $v;
            $adj[$v][] = $u;
        }

        $coprime = [];
        for ($x = 1; $x <= 50; $x++) {
            $coprime[$x] = [];
            for ($y = 1; $y <= 50; $y++) {
                if ($this->gcd($x, $y) == 1) {
                    $coprime[$x][] = $y;
                }
            }
        }

        $last = array_fill(1, 50, -1);
        $ans = array_fill(0, $n, -1);
        $depth = array_fill(0, $n, 0);
        $parent = array_fill(0, $n, -1);
        $prevForNode = array_fill(0, $n, -1);

        $stack = [1]; // node 0 enter event (node + 1)

        while (!empty($stack)) {
            $e = array_pop($stack);
            if ($e > 0) {
                $u = $e - 1;
                $val = $nums[$u];

                $best = -1;
                $bestDepth = -1;
                foreach ($coprime[$val] as $y) {
                    $cand = $last[$y];
                    if ($cand != -1 && $depth[$cand] > $bestDepth) {
                        $bestDepth = $depth[$cand];
                        $best = $cand;
                    }
                }
                $ans[$u] = $best;

                $prevForNode[$u] = $last[$val];
                $last[$val] = $u;

                $stack[] = -($u + 1);

                foreach ($adj[$u] as $w) {
                    if ($w != $parent[$u]) {
                        $parent[$w] = $u;
                        $depth[$w] = $depth[$u] + 1;
                        $stack[] = $w + 1;
                    }
                }
            } else {
                $u = -$e - 1;
                $last[$nums[$u]] = $prevForNode[$u];
            }
        }

        return $ans;
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $t = $a % $b;
            $a = $b;
            $b = $t;
        }
        return $a;
    }
}
```

