class Solution {

    /**
     * @param String $s1
     * @param String $s2
     * @return String[]
     */
    function uncommonFromSentences($s1, $s2) {
        $counts = [];
        $allWords = explode(' ', $s1 . ' ' . $s2);

        foreach ($allWords as $word) {
            if (!isset($counts[$word])) {
                $counts[$word] = 0;
            }
            $counts[$word]++;
        }

        $result = [];
        foreach ($counts as $word => $count) {
            if ($count === 1) {
                $result[] = $word;
            }
        }

        return $result;
    }
}
```

