        for ($i = 0; $i < $n; $i++) {
            if ($indegree[$i] == 0) {
                if ($root != -1) {
                    return false;
                }
                $root = $i;
            }
        }

        if ($root == -1) {
            return false;
        }

        $visited = array_fill(0, $n, false);
        $stack = [$root];
        $visited[$root] = true;
        $count = 0;

