```php
class Solution {

    /**
     * @param String $s
     * @param String $p
     * @return Boolean
     */
    function isMatch($s, $p) {
        $n = strlen($s);
        $m = strlen($p);

        $i = 0;
        $j = 0;
        $star = -1;
        $match = 0;

        while ($i < $n) {
            if ($j < $m && ($p[$j] == '?' || $p[$j] == $s[$i])) {
                $i++;
                $j++;
            } elseif ($j < $m && $p[$j] == '*') {
                $star = $j;
                $match = $i;
                $j++;
            } elseif ($star != -1) {
                $j = $star + 1;
                $match++;
                $i = $match;
            } else {
                return false;
            }
        }

        while ($j < $m && $p[$j] == '*') {
            $j++;
        }

        return $j == $m;
    }
}
```

